#ksBnr .dnw{position:relative;flex:none;width:390px;height:160px;overflow:hidden;background:#E9DDB2}
#ksBnr .dnw>*{position:absolute;display:block}
#ksBnr .dnw i,#ksBnr .dnw i>img{position:absolute;display:block}
#ksBnr .dnw .bnr{left:0;top:0;width:390px;height:160px;object-fit:cover}
